#!/usr/bin/env node
const NINTH_ORIGINAL_URL=new URL("../../../../../model-alignment/verify-model-alignment.mjs",import.meta.url);
import {eighthLeaf,eighthQuestion} from '../eighth-reconciliation/verify-dependencies.mjs';
// Final acceptance reads the requested actual dist only. No overlay, fallback, project imports or writes.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(NINTH_ORIGINAL_URL));const pos=process.argv.indexOf('--dist');assert.ok(pos>=0&&process.argv[pos+1],'--dist must name the actual final dist');assert.ok(!process.argv.includes('--mode'),'There is no candidate mode or overlay');
const dist=path.resolve(process.argv[pos+1]);const load=n=>JSON.parse(fs.readFileSync(path.join(here,n),'utf8'));const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const recordText=fs.readFileSync(path.join(here,'records.json'),'utf8'),pkg=JSON.parse(recordText),app=load('append-manifest.json'),identity=load('identity-baseline.json'),map=load('preservation-map.json'),variants=load('variant-map.json'),sourceRows=load('source-row-map.json');
const E=new Map();for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(x=>x.endsWith('.json')))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f),'utf8')).entries||[]){assert.ok(!E.has(e.id));E.set(e.id,e);}
const checks=[];const check=(name,fn)=>{try{checks.push({name,status:'passed',...fn()});}catch(e){checks.push({name,status:'failed',error:e.message});}};
const target=key=>{const [id,q]=key.split('#'),e=E.get(id);assert.ok(e,`entry ${id} missing`);if(q===undefined)return e;const x=e.items?.find((x,i)=>String(x.id??i)===q);assert.ok(x,`question ${key} missing`);return x;};
const at=(e,p)=>p.reduce((v,k)=>v[k],e);const blocks=s=>[...s.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)];
const exactDest=d=>{assert.equal(sha(d.html),d.sha256);const value=d.field?target(d.stableReviewKey)[d.field]:target(d.stableReviewKey).a;assert.ok(value.includes(d.html),`exact substantive destination missing: ${d.stableReviewKey} ${d.section}`);};
const balanced=s=>{const st=[],voids=new Set(['br','hr','img','input','meta','link','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){const tag=m[2].toLowerCase();if(m[1])assert.equal(st.pop(),tag);else if(!voids.has(tag)&&!m[0].endsWith('/>'))st.push(tag);}assert.deepEqual(st,[]);};
check('twelve-exact-final-leaves-no-overlay',()=>{assert.equal(pkg.records.length,12);assert.deepEqual(pkg.records.map(r=>({entryId:r.entryId,path:r.path})),identity.changedLeaves);assert.equal(new Set(pkg.records.map(r=>r.entryId+JSON.stringify(r.path))).size,12);for(const r of pkg.records){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);assert.equal(at(E.get(r.entryId),r.path),eighthLeaf(r.entryId,r.path,r.after),`Unapplied or drifted leaf ${r.entryId}/${r.path.join('/')}`);}return {leaves:12,alreadyApplied:12,stagedInMemory:0,siteWrites:0};});
check('three-exact-stable-appends',()=>{assert.equal(app.additions.length,3);for(const a of app.additions){const e=E.get(a.entryId),x=target(a.entryId+'#'+a.questionId);assert.equal(e.items.indexOf(x),a.expectedIndex);assert.equal(sha(x.a),a.afterSha256);assert.deepEqual(x,a.expectedItem);}return {appends:3,stagedInMemory:0};});
check('thirty-old-identities-and-prefix-indexes',()=>{
 const text=fs.readFileSync(path.join(here,'sixth-metrics-reconciliation.json'),'utf8');assert.equal(sha(text),'e721418f604f18543218afc6dd6e09bcf1de9cedcb445af956dcf892423825b2','Sixth math reconciliation proof changed');const r=JSON.parse(text);
 for(const [name,hash] of Object.entries(r.preservedOriginalFixtureHashes))assert.equal(sha(fs.readFileSync(path.join(here,name))),hash,'Original alignment fixture changed '+name);
 assert.equal(r.beforeEntry.id,'own-theory-math');assert.equal(r.beforeEntry.items.length,6);assert.equal(r.metricsOriginalFiveQuestionEntry.items.length,5);assert.deepEqual(r.beforeEntry.items.slice(0,5),r.metricsOriginalFiveQuestionEntry.items);
 const prior=app.additions.find(a=>a.entryId==='own-theory-math');assert.deepEqual(prior,r.originalAlignmentAppend);assert.equal(prior.expectedIndex,5);assert.deepEqual(r.beforeEntry.items[5],prior.expectedItem);
 const m=r.metricsPrefixRecord;assert.equal(m.entryId,'own-theory-math');assert.deepEqual(m.path,['items',3,'a']);assert.equal(m.mode,'exact-old-prefix-plus-append');assert.equal(sha(m.before),m.beforeSha256);assert.equal(sha(m.after),m.afterSha256);assert.equal(r.beforeEntry.items[3].a,m.before);assert.ok(m.after.startsWith(m.before));assert.ok(m.after.length>m.before.length);
 const a=r.metricsAppend;assert.equal(a.entryId,'own-theory-math');assert.equal(a.questionId,'q-model-auc-gauc');assert.equal(a.expectedIndex,6);assert.equal(a.expectedOldCount,6);assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);assert.equal(sha(a.expectedItem.a),a.afterSha256);
 const expected=structuredClone(r.beforeEntry);expected.items[3].a=m.after;expected.items.push(a.expectedItem);assert.equal(expected.items.length,7);assert.deepEqual(E.get('own-theory-math'),expected,'All seven complete mathematical question objects must match the exact composition');
 let count=0;for(const b of identity.entries){const e=E.get(b.entryId);assert.ok(e);const n=app.additions.filter(x=>x.entryId===b.entryId).length;const extra=b.entryId==='own-theory-math'?1:0;assert.equal(e.items.length,b.oldCount+n+extra);assert.deepEqual(Object.fromEntries(Object.entries(e).filter(([k])=>!['items','number'].includes(k))),b.entryFields);const m=typeof b.numberBefore==='string'&&b.numberBefore.match(/^(\s*)\d+(\s*问\s*)$/);assert.equal(e.number,m?m[1]+e.items.length+m[2]:b.numberBefore);for(let i=0;i<b.oldCount;i++){assert.deepEqual(Object.fromEntries(Object.entries(e.items[i]).filter(([k])=>!['a','lead'].includes(k))),eighthQuestion(b.entryId,i,b.identities[i]));count++;}}assert.equal(count,30);return {oldQuestions:count,entries:3,mathOldObjects:6,mathFinalObjects:7,exactPrefixExtensions:1,metricsAppendIndex:6};
});
check('all210-source-blocks-resolve-to-substantive-exact-destinations',()=>{assert.equal(map.recordFileSha256,sha(recordText));let n=0;for(const m of map.maps){const r=pkg.records.find(r=>r.entryId+'#'+r.path[1]===m.stableReviewKey&&r.path[2]==='a');assert.ok(r);assert.equal(m.beforeSha256,sha(r.before));assert.equal(m.afterSha256,sha(r.after));const bs=blocks(r.before);assert.equal(bs.length,m.sourceBlockCount);assert.equal(bs.length,m.blocks.length);for(const [i,b] of m.blocks.entries()){assert.equal(b.sourceBlockIndex,i);assert.equal(bs[i][0],b.sourceHtml);assert.equal(sha(b.sourceHtml),b.sourceSha256);assert.equal(Array.from(r.before).slice(...b.sourceSpanCodePoints).join(''),b.sourceHtml);assert.ok(b.destinations.length>0);b.destinations.forEach(exactDest);n++;}}assert.equal(n,210);assert.equal(n,map.sourceCount);return {mappedBlocks:n};});
check('all25-variants-and32-inline-question-blocks-preserved',()=>{assert.equal(variants.originalVariantCount,25);assert.equal(variants.variants.length,25);assert.equal(variants.inlineQuestionBlockCount,32);assert.equal(variants.inlineQuestionBlocks.length,32);for(const v of [...variants.variants,...variants.inlineQuestionBlocks]){const m=map.maps.find(x=>x.stableReviewKey===v.sourceKey),b=m.blocks[v.sourceBlockIndex];assert.equal(v.sourceHtml,b.sourceHtml);assert.equal(v.sourceSha256,sha(v.sourceHtml));assert.equal(v.original,b.sourceText);assert.ok(v.destinations.length);v.destinations.forEach(exactDest);}for(const v of variants.variants){const body=target(v.sourceKey).a;assert.ok(body.includes(v.original),`exact old wording absent from old route ${v.sourceKey}: ${v.original}`);}return {variants:25,inlineQuestionBlocks:32};});
check('all25-original-source-rows-have-compound-coverage',()=>{assert.equal(sourceRows.sourceRows,25);assert.equal(sourceRows.rows.length,25);assert.equal(new Set(sourceRows.rows.map(x=>x.sourceRecordId)).size,25);for(const row of sourceRows.rows){assert.equal(sha(row.exactOriginalQuestion),row.exactQuestionSha256);const v=variants.variants.find(v=>v.sourceKey===row.originalDestination&&v.original===row.exactOriginalQuestion);assert.ok(v,row.sourceRecordId);assert.ok(row.compoundComponents.length);assert.deepEqual(row.destinations,v.destinations);row.destinations.forEach(exactDest);}return {sourceRows:25};});
check('html-aliases-and-all-internal-routes-resolve',()=>{let routes=0,anchors=0;for(const s of [...pkg.records.map(r=>r.after),...app.additions.map(a=>a.expectedItem.a)]){balanced(s);assert.ok(!/<(?:pre|script|style|iframe)\b/i.test(s));assert.ok(!/href="https?:/.test(s),'No new public external reference paragraphs');for(const m of s.matchAll(/href="#\/e\/([^"/]+)(?:\/([^"/]+))?"/g)){target(decodeURIComponent(m[1])+(m[2]?'#'+decodeURIComponent(m[2]):''));routes++;}}for(const r of pkg.records)for(const m of r.before.matchAll(/\bid="([^"]+)"/g)){assert.ok(r.after.includes(`id="${m[1]}"`));anchors++;}const alias=target('ai-模型与评测-5#6').a;assert.ok(alias.includes('#/e/ai-模型与评测-4/q-model-dpo-objective-data'));assert.ok(!alias.includes('L_DPO='));assert.ok(!alias.includes('0.15/0.05'));return {routes,retainedAnchors:anchors,oldDpoRoute:'exact pointer'};});
check('key-conditions-and-no-duplicate-major-mechanisms',()=>{const s=target('ai-模型与评测-4#2').a,r=target('ai-模型与评测-4#3').a,o=target('ai-模型与评测-4#4').a,d=target('ai-模型与评测-4#q-model-dpo-objective-data').a,t=target('ai-模型与评测-4#q-model-r1-training-stages').a,b=target('own-theory-math#q-model-bias-variance-boundary').a,c=target('ai-模型与评测-4#10').a;
for(const term of ['可靠区分','预算足以','更新权重','API 接入'])assert.ok((s).includes(term),term);
for(const term of ['rφ(x,yw)','critic','reference-KL','固定四份或五份'])assert.ok(r.includes(term),term);
for(const term of ['独立 critic','不等同整套 RLHF','ε=0.2','不是梯度范数裁剪'])assert.ok(o.includes(term),term);
for(const term of ['β&gt;0','0.2/0.1','0.15/0.05','sum','mean','不存在普适 3:7','未展示候选','reference 固定','负例之间的顺序','选择与展示偏差'])assert.ok(d.includes(term),term);
assert.equal((d.match(/L_DPO=/g)||[]).length,1);assert.equal((d.match(/0\.15\/0\.05/g)||[]).length,1);assert.equal((o.match(/A=1,r=1\.5/g)||[]).length,1);
for(const term of ['DeepSeek-V3-Base','两次 SFT 加两次 RL','有帮助主要评价最终摘要','无害性评价整个回答','相同总 rollout'])assert.ok(t.includes(term),term);
for(const term of ['测试噪声与训练集 D 独立','有限二阶矩','平方损失','Var(ε|x)'])assert.ok(b.includes(term),term);
for(const term of ['从起点就没有收益','F/(c_old−c_new)','删除和来源解释更难','每成功任务成本'])assert.ok(c.includes(term),term);
assert.ok(!s.includes('R1-Zero 不先做 SFT'));assert.ok(!s.includes('−log σ(rφ'));assert.ok(!target('ai-模型与评测-4#11').a.includes('E[(y−'));
return {conditions:'preserved',dpoFormulaCopies:1,probabilityCounterexampleCopies:1,ppoFourCaseCopies:1};});
check('dpo-relative-probability-counterexample',()=>{const loss=(w,l,rw,rl,beta)=>Math.log1p(Math.exp(-beta*(Math.log(w/rw)-Math.log(l/rl))));for(const beta of [.1,1,3]){const old=loss(.2,.1,.2,.1,beta),next=loss(.15,.05,.2,.1,beta);assert.ok(next<old);assert.ok(.15<.2&&.05<.1);assert.ok(Math.abs((.15/.05)/(.2/.1)-1.5)<1e-12);}return {fixedReference:true,positiveBetas:3,scope:'Arithmetic only; no DPO training performed'};});
check('ppo-four-sign-branches-and-loss-sign',()=>{const clip=x=>Math.min(1.2,Math.max(.8,x)),value=(a,r)=>Math.min(r*a,clip(r)*a);const cases=[[1,1.5,1.2],[-1,.5,-.8],[1,.5,.5],[-1,1.5,-1.5]];for(const [a,r,want] of cases){assert.ok(Math.abs(value(a,r)-want)<1e-12);assert.equal(-value(a,r),-want);}return {cases:4,scope:'Arithmetic of surrogate only; no policy optimization performed'};});
check('bias-variance-conditions-and-finetuning-break-even',()=>{const pred=[2,4],noise=[-1,1],truth=2;let mse=0;for(const p of pred)for(const z of noise)mse+=(truth+z-p)**2/4;const mean=3,bias=(mean-truth)**2,variance=pred.reduce((n,x)=>n+(x-mean)**2/2,0);assert.equal(mse,bias+variance+1);const breakeven=(f,old,next)=>{assert.ok(f>=0&&old>next,'positive cost saving required');return f/(old-next);};assert.equal(breakeven(100,3,2),100);assert.throws(()=>breakeven(100,2,2));assert.throws(()=>breakeven(100,2,3));return {squaredLossMse:mse,biasSquared:bias,modelVariance:variance,noiseVariance:1,scope:'Illustrative finite arithmetic, not a model benchmark or cost forecast'};});
console.log(JSON.stringify({mode:'final',dist,recordsSha256:sha(recordText),verifierSha256:sha(fs.readFileSync(fileURLToPath(import.meta.url))),passed:checks.filter(x=>x.status==='passed').length,failed:checks.filter(x=>x.status==='failed').length,total:checks.length,siteWrites:0,stagedInMemory:0,actualFinalDistAcceptance:checks.every(x=>x.status==='passed'),checks,limitations:['No build, browser rendering, GPU training or performance test was run.','A passing synthetic preview is not actual final-dist acceptance.','Source maps preserve reviewed scope only, not all source documents.']},null,2));if(checks.some(x=>x.status==='failed'))process.exitCode=1;
